// src/core/tenants/tenant.routes.ts
import { FastifyPluginAsync } from 'fastify';
import { tenantService } from './tenant.service';
import { setTenantRegionSchema } from './tenant.schemas';

const tenantRoutes: FastifyPluginAsync = async (fastify) => {
  /**
   * POST /tenants/:tenantId/set-region
   * Define a região do tenant (país, estado, cidade)
   * Usa root-config como fallback se algum campo não for fornecido
   */
  fastify.post<{
    Params: { tenantId: string };
    Body: {
      countryId?: string | null;
      stateId?: string | null;
      cityId?: string | null;
    };
  }>(
    '/:tenantId/set-region',
    {
      schema: {
        params: {
          type: 'object',
          required: ['tenantId'],
          properties: {
            tenantId: { type: 'string' },
          },
        },
        body: {
          type: 'object',
          properties: {
            countryId: { type: ['string', 'null'] },
            stateId: { type: ['string', 'null'] },
            cityId: { type: ['string', 'null'] },
          },
        },
      },
    },
    async (req, reply) => {
      try {
        const { tenantId } = req.params;
        const validated = setTenantRegionSchema.parse(req.body);

        const tenant = await tenantService.setTenantRegion(tenantId, validated);
        return reply.status(200).send(tenant);
      } catch (error) {
        if (error instanceof Error) {
          return reply.status(400).send({ error: error.message });
        }
        return reply.status(500).send({ error: 'Erro ao definir região do tenant' });
      }
    }
  );
};

export default tenantRoutes;
















